INSERT INTO `evaluations` (`id`, `event_id`, `name`, `description`, `event`, `qr_code_path`, `form_data`, `is_active`, `is_archived`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Hospitality Workshop Evaluation', 'Evaluation form for the Hospitality Management Workshop participant feedback and satisfaction assessment.', 'Hospitality Management Workshop', 'qr_hm_workshop.png', '{"questions": [{"id": 1, "type": "rating", "question": "How would you rate the overall quality of the workshop?", "required": true, "scale": 5}, {"id": 2, "type": "rating", "question": "How relevant was the content to your studies?", "required": true, "scale": 5}, {"id": 3, "type": "text", "question": "What did you find most valuable about this workshop?", "required": false}, {"id": 4, "type": "text", "question": "Suggestions for improvement?", "required": false}]}', 1, 0, '2025-10-10 10:30:00', '2025-10-10 10:30:00'),
	(2, 2, 'Business Leadership Summit Feedback', 'Feedback form for the Business Leadership Summit to assess speaker effectiveness and content relevance.', 'Business Leadership Summit', 'qr_ba_summit.png', '{"questions": [{"id": 1, "type": "rating", "question": "Rate the quality of the speakers", "required": true, "scale": 5}, {"id": 2, "type": "rating", "question": "How valuable were the networking opportunities?", "required": true, "scale": 5}, {"id": 3, "type": "multiple", "question": "Which topics were most beneficial?", "required": true, "options": ["Leadership Strategies", "Industry Trends", "Career Development", "Innovation"]}, {"id": 4, "type": "text", "question": "Additional comments or suggestions?", "required": false}]}', 1, 0, '2025-10-12 14:20:00', '2025-10-12 14:20:00'),
	(3, 3, 'Criminal Justice Symposium Evaluation', 'Evaluation form for the Criminal Justice Symposium focusing on content relevance and speaker effectiveness.', 'Criminal Justice Symposium', 'qr_cj_symposium.png', '{"questions": [{"id": 1, "type": "rating", "question": "How informative were the presentations?", "required": true, "scale": 5}, {"id": 2, "type": "rating", "question": "How relevant was this symposium to your career goals?", "required": true, "scale": 5}, {"id": 3, "type": "text", "question": "Key takeaways from the symposium?", "required": false}, {"id": 4, "type": "text", "question": "Topics you would like to see in future events?", "required": false}]}', 1, 0, '2025-10-11 09:15:00', '2025-10-11 09:15:00'),
	(4, 4, 'Teaching Methods Seminar Feedback', 'Feedback form for the Teaching Methods Seminar evaluating teaching innovation and practical applications.', 'Teaching Methods Seminar', 'qr_te_seminar.png', '{"questions": [{"id": 1, "type": "rating", "question": "How innovative were the teaching methods presented?", "required": true, "scale": 5}, {"id": 2, "type": "rating", "question": "How likely are you to apply these methods in your future teaching?", "required": true, "scale": 5}, {"id": 3, "type": "multiple", "question": "Which methods were most interesting?", "required": true, "options": ["Technology Integration", "Project-Based Learning", "Assessment Techniques", "Classroom Management"]}, {"id": 4, "type": "text", "question": "Additional teaching methods you would like to explore?", "required": false}]}', 1, 0, '2025-10-09 11:45:00', '2025-10-09 11:45:00'),
	(5, 5, 'IT Hackathon Experience Survey', 'Survey for IT Hackathon participants evaluating organization, challenges, and overall experience.', 'IT Innovation Hackathon', 'qr_it_hackathon.png', '{"questions": [{"id": 1, "type": "rating", "question": "How well was the hackathon organized?", "required": true, "scale": 5}, {"id": 2, "type": "rating", "question": "How challenging were the problems presented?", "required": true, "scale": 5}, {"id": 3, "type": "multiple", "question": "What aspects did you enjoy most?", "required": true, "options": ["Problem Solving", "Team Collaboration", "Time Pressure", "Learning New Technologies"]}, {"id": 4, "type": "text", "question": "Suggestions for improving future hackathons?", "required": false}]}', 1, 0, '2025-10-13 16:20:00', '2025-10-13 16:20:00');
